1	"use server";
2	
3	import { createClient } from "@/lib/supabase/server";
4	import { signItemImages, displayPath } from "@/lib/storage/signed";
5	import { fetchForecast } from "@/lib/weather/open-meteo";
6	import { laterAdvice } from "@/lib/weather/advice";
7	import { readPreferences } from "@/lib/profile/preferences";
8	import { personalBand } from "@/lib/generator/rules";
9	import { buildCandidates, type CandidateItem } from "@/lib/generator/candidates";
10	import { rankTopN } from "@/lib/generator/rank";
11	import { currentSeason } from "@/lib/generator/season";
12	import { rerank } from "@/lib/generator/rerank";
13	import { layoutForLook, staggerOrder } from "@/lib/generator/layout";
14	import { localDateFor } from "@/lib/outfits/local-date";
15	import { assertCanGenerate, noteGeneration, QuotaExceededError } from "@/lib/outfits/quota";
16	import { predictOccasion } from "@/lib/outfits/predict-occasion";
17	import { pinItem, styledLookName, shortlistFor } from "@/lib/outfits/styled";
18	import { loadStyledLook, saveStyledLook } from "@/lib/outfits/styled-store";
19	import { resolveLocation } from "@/lib/weather/location";
20	import type { LookDraft, LookPiece, WeatherPayload } from "@/lib/generator/types";
21	
22	export type StyleResult =
23	  | { status: "ok"; outfitId: string }
24	  // Carries the seam's own reason. Styling is a Pro capability rather than a
25	  // daily allowance, so a message written here ("back tomorrow") would be
26	  // actively false — tomorrow gives a free user no stylings either.
27	  | { status: "limited"; message: string }
28	  | { status: "empty"; message: string }
29	  | { status: "error"; message: string };
30	
31	/**
32	 * "Style an outfit with this" (Fitcheck.dc.html:654).
33	 *
34	 * Pins the piece, runs the deterministic pipeline, spends ONE text call to name
35	 * and explain the result, then persists it keyed by (user, item, local day) so a
36	 * second tap the same day is a free read.
37	 *
38	 * This does not contradict Decision 5. That decision says never pay twice for a
39	 * question already answered — which is why the daily drop caches. "What goes
40	 * with this piece?" is a different question from "what should I wear today?",
41	 * so it gets its own answer, cached the same way.
42	 *
43	 * The alternative readings were measured and rejected; see the plan
44	 * `todo/2026-07-24-item-detail-rebuild.md`.
45	 */
46	export async function styleWithItem(itemId: string): Promise<StyleResult> {
47	  try {
48	    const supabase = await createClient();
49	    const {
50	      data: { user },
51	    } = await supabase.auth.getUser();
52	    if (!user) return { status: "error", message: "Not signed in" };
53	
54	    const { data: profile } = await supabase
55	      .from("profiles")
56	      .select(
57	        "archetype, formality_min, formality_max, occasions, location_lat, location_lon, location_label, location_source, location_timezone, preferences",
58	      )
59	      .eq("id", user.id)
60	      .single();
61	
62	    const { data: itemsRaw } = await supabase
63	      .from("items")
64	      .select("*")
65	      .eq("user_id", user.id)
66	      .eq("archived", false);
67	    const items = itemsRaw ?? [];
68	    const subject = items.find((i) => i.id === itemId);
69	    if (!subject) return { status: "error", message: "Piece not found" };
70	
71	    // Fragrance occupies no slot in a look, so there is nothing to build around.
72	    if (subject.category === "Fragrance") {
73	      return { status: "empty", message: "Fragrance finishes a look rather than forming one." };
74	    }
75	
76	    const now = new Date();
77	    // The date key comes from the PROFILE timezone, not the forecast's, so the
78	    // cache can be checked without a network call — the same zone `toggleWear`
79	    // and `predictDefaultOccasion` use.
80	    const today = localDateFor(now, profile?.location_timezone ?? "UTC");
81	
82	    // THE CACHE. Checked before the quota is touched and before any I/O beyond
83	    // this one indexed lookup — re-opening an answer you already have must never
84	    // cost anything.
85	    const cached = await loadStyledLook(user.id, itemId, today);
86	    if (cached) return { status: "ok", outfitId: cached };
87	
88	    // Checked before the forecast fetch below: a free user is turned away
89	    // without us paying for I/O they will never see. The occasion is not needed
90	    // here — a styled look is a flat capability (Pro #2), not a counted meter —
91	    // and it is resolved a few lines down, in time for the ledger.
92	    try {
93	      await assertCanGenerate(user.id, { kind: "styled", today });
94	    } catch (e) {
95	      if (e instanceof QuotaExceededError) return { status: "limited", message: e.message };
96	      throw e;
97	    }
98	
99	    const loc = resolveLocation({ profile });
100	    const f = await fetchForecast(loc.lat, loc.lon);
101	    const prefs = readPreferences(profile?.preferences);
102	    const advice = laterAdvice(f.hourly, prefs.tempUnit);
103	    const weather: WeatherPayload = {
104	      tempC: f.tempC,
105	      feelsLikeC: f.feelsLikeC,
106	      condition: f.condition,
107	      cityLabel: loc.label,
108	      timezone: f.timezone,
109	      locationOrigin: loc.origin,
110	      laterSentence: advice.sentence,
111	      adviceClause: advice.adviceClause,
112	      laterLabel: "Later",
113	      hourly: f.hourly,
114	      tempUnit: prefs.tempUnit,
115	    };
116	
117	    // The occasion the app already believes you are dressing for today — the CTA
118	    // has no picker, and a look styled for the wrong context is worse than one
119	    // that simply agrees with the rest of the day.
120	    const occasion = predictOccasion(now, f.timezone, profile?.occasions ?? []);
121	
122	    /**
123	     * Pinning, done BEFORE candidate building rather than after.
124	     *
125	     * Dropping every rival in the subject's own category means any combo using
126	     * that category uses THIS piece. Filtering the built list instead would have
127	     * to survive the 200-combo CAP, and a piece that never made the cut would
128	     * silently produce "no looks" — the same class of bug as the coverage
129	     * defect fixed in PR #14.
130	     */
131	    const pool = items.filter((i) => i.category !== subject.category || i.id === itemId);
132	    const candItems: CandidateItem[] = pool.map((i) => ({
133	      id: i.id,
134	      colors: i.colors ?? [],
135	      category: i.category,
136	      formality: i.formality,
137	      seasons: i.seasons ?? [],
138	      material: i.material,
139	    }));
140	
141	    const args = {
142	      weather: { tempC: f.tempC, rain: f.hourly.some((h) => h.isNow && h.rain) },
143	      season: currentSeason(now),
144	      excludeItemIds: [],
145	      maxAccessories: 1,
146	      rainGuard: prefs.rainGuard,
147	    };
148	    const aesthetic = profile?.archetype ? [profile.archetype] : [];
149	
150	    // Try the day's own formality band first, then the full scale. A piece
151	    // dressier or more casual than today's context is still stylable — refusing
152	    // would be the "hard filter empties a required slot" trap again.
153	    let pinned: ReturnType<typeof rankTopN> = [];
154	    for (const band of [personalBand(occasion, profile), [1, 5] as [number, number]]) {
155	      const combos = buildCandidates(candItems, { ...args, band });
156	      const ranked = rankTopN(
157	        combos,
158	        { aesthetic, band, lean: [], recentlyShown: [], season: args.season },
159	        combos.length,
160	      );
161	      pinned = pinItem(ranked, itemId);
162	      if (pinned.length) break;
