1	type Keyed = { id: string; category: string };
2	
3	function slotId(items: Keyed[], category: string): string | undefined {
4	  return items.find((i) => i.category === category)?.id;
5	}
6	
7	/**
8	 * Order and size the shortlist handed to the re-ranker.
9	 *
10	 * Ranking alone clusters: a neutral top harmonises with everything, so combos
11	 * containing it occupy most of the top of the list. Hand the model that raw and
12	 * it returns three variations of one outfit.
13	 *
14	 * So the shortlist is TIERED rather than filtered. Combos whose top and bottom
15	 * are both unused come first, then those with one unused slot, then the rest —
16	 * score-descending inside each tier. The model still sees maximally-distinct
17	 * options at the head of the list, so "the best 3" are naturally distinct, but
18	 * the tail is no longer thrown away.
19	 *
20	 * Why the tail matters: an earlier version returned ONLY the fully-distinct
21	 * combos (floor 3). On a real 21-item closet that handed the re-ranker 6
22	 * candidates in summer and 3 in winter, out of 48 and 21 valid ones — so
23	 * Regenerate could not return anything different, and shoe variation was
24	 * unreachable in every season. Three looks sharing trousers but differing in
25	 * top and shoes are three different looks; only a repeated COMBINATION is a
26	 * duplicate, and buildCandidates never emits one.
27	 */
28	export function diversify<T extends { items: Keyed[]; score: number }>(
29	  ranked: T[],
30	  n: number,
31	): T[] {
32	  const usedTops = new Set<string>();
33	  const usedBottoms = new Set<string>();
